using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using RafeekRoomMate.Domain.Entities;
using RafeekRoomMate.Infrastructure.Persistence.Identity;

namespace RafeekRoomMate.Infrastructure.Persistence.Configurations
{
    public sealed class UserProfileConfiguration : IEntityTypeConfiguration<UserProfile>
    {
        public void Configure(EntityTypeBuilder<UserProfile> builder)
        {
            // Table
            builder.ToTable("UserProfiles");

            // Primary Key
            builder.HasKey(x => x.Id);

            // Id generated by application
            builder.Property(x => x.Id).ValueGeneratedNever();

            // UserId
            builder.Property(x => x.UserId).IsRequired();

            // One User -> One Profile
            builder.HasIndex(x => x.UserId).IsUnique();

            // Relationship with Identity User
            builder.HasOne<User>().WithOne().HasForeignKey<UserProfile>(x => x.UserId).OnDelete(DeleteBehavior.Cascade);

            // Profile information
            builder.Property(x => x.Bio).HasMaxLength(1000);

            builder.Property(x => x.Occupation).HasMaxLength(150);

            // Location
            builder.Property(x => x.City).HasMaxLength(100);

            builder.Property(x => x.Area).HasMaxLength(150);

            // Budget
            builder.Property(x => x.MonthlyBudget).HasPrecision(18, 2);

            // Preferences
            builder.Property(x => x.PreferredRoommateGender).HasMaxLength(50);

            // Profile image storage key
            builder.Property(x => x.ProfileImageKey).HasMaxLength(500);

            // Audit
            builder.Property(x => x.CreatedAt).IsRequired();

            builder.Property(x => x.UpdatedAt);

            // Search indexes
            builder.HasIndex(x => x.City);

            builder.HasIndex(x => x.MonthlyBudget);
        }
    }
}
